import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-secret-key-change-me')

DB_PATH = os.environ.get('DB_PATH', '/data/users.db')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    conn.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        email TEXT,
        api_key TEXT
    )''')
    conn.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    conn.commit()
    conn.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if api_key:
            conn = get_db()
            user = conn.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
            conn.close()
            if user:
                request.current_user = dict(user)
                return f(*args, **kwargs)
        if 'user_id' in session:
            conn = get_db()
            user = conn.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
            conn.close()
            if user:
                request.current_user = dict(user)
                return f(*args, **kwargs)
        return jsonify({'error': 'unauthorized'}), 401
    return decorated

@app.route('/api/users/search', methods=['GET'])
@require_auth
def search_users():
    query = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Build query - field is validated above so safe to interpolate
    # But the query value uses string formatting for LIKE pattern
    sql = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{query}%'"

    conn = get_db()
    try:
        results = conn.execute(sql).fetchall()
        users = [dict(r) for r in results]
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        users = []
    finally:
        conn.close()

    return jsonify({'results': users})

@app.route('/api/users/<int:user_id>', methods=['GET'])
@require_auth
def get_user(user_id):
    conn = get_db()
    user = conn.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    conn.close()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users/profile', methods=['PUT'])
@require_auth
def update_profile():
    data = request.get_json()
    allowed_updates = ['email']
    updates = {k: v for k, v in data.items() if k in allowed_updates}

    if not updates:
        return jsonify({'error': 'no valid fields'}), 400

    set_clause = ', '.join(f"{k} = ?" for k in updates.keys())
    values = list(updates.values()) + [request.current_user['id']]

    conn = get_db()
    conn.execute(f"UPDATE users SET {set_clause} WHERE id = ?", values)
    conn.commit()
    conn.close()

    return jsonify({'status': 'updated'})

@app.route('/api/admin/export', methods=['POST'])
@require_auth
def export_data():
    if request.current_user.get('role') != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    table = request.json.get('table', 'users')
    # Only allow specific tables
    if table not in ['users', 'audit_log']:
        return jsonify({'error': 'invalid table'}), 400

    conn = get_db()
    rows = conn.execute(f"SELECT * FROM {table}").fetchall()
    conn.close()

    return jsonify({'data': [dict(r) for r in rows]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
